contracts/MarketFactoryV3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./PredictionMarketV3.sol";
import "./MultiOutcomeMarket.sol";

/// @title MarketFactoryV3 — binary CPMM + multi-outcome markets
contract MarketFactoryV3 is Ownable, Pausable {
    IERC20 public immutable collateral;
    address public oracle;
    uint16 public defaultFeeBps;
    uint256 public defaultMaxBet;

    uint256 public marketCount;
    mapping(uint256 => address) public markets;
    mapping(uint256 => uint8) public marketTypes; // 0=binary v3, 1=multi

    event BinaryMarketCreated(uint256 indexed id, address market, bytes32 matchRef, string question);
    event MultiMarketCreated(uint256 indexed id, address market, uint8 outcomes, string question);

    constructor(address _collateral, address _oracle, uint16 _feeBps) Ownable(msg.sender) {
        collateral = IERC20(_collateral);
        oracle = _oracle;
        defaultFeeBps = _feeBps;
        defaultMaxBet = 10_000 * 1e6;
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    function setOracle(address _oracle) external onlyOwner { oracle = _oracle; }
    function setDefaultFeeBps(uint16 bps) external onlyOwner { defaultFeeBps = bps; }

    function createBinaryMarket(
        bytes32 matchRef,
        string calldata question,
        uint256 endTime,
        uint256 initialLiquidity
    ) external onlyOwner whenNotPaused returns (address market, uint256 id) {
        PredictionMarketV3 m = new PredictionMarketV3(
            address(collateral),
            oracle,
            address(this),
            matchRef,
            question,
            endTime,
            defaultFeeBps,
            initialLiquidity,
            defaultMaxBet
        );
        id = ++marketCount;
        market = address(m);
        markets[id] = market;
        marketTypes[id] = 0;
        emit BinaryMarketCreated(id, market, matchRef, question);
    }

    function createMultiMarket(
        bytes32 matchRef,
        string calldata question,
        uint256 endTime,
        uint8 outcomeCount
    ) external onlyOwner whenNotPaused returns (address market, uint256 id) {
        MultiOutcomeMarket m = new MultiOutcomeMarket(
            address(collateral),
            oracle,
            matchRef,
            question,
            endTime,
            outcomeCount,
            defaultFeeBps
        );
        id = ++marketCount;
        market = address(m);
        markets[id] = market;
        marketTypes[id] = 1;
        emit MultiMarketCreated(id, market, outcomeCount, question);
    }

    function version() external pure returns (string memory) {
        return "3.0.0-phase3";
    }
}

contracts/MultiOutcomeMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title MultiOutcomeMarket — N-outcome parimutuel (2-8 outcomes)
contract MultiOutcomeMarket is ReentrancyGuard {
    using SafeERC20 for IERC20;

    enum Status { Open, Resolved, Voided }

    IERC20 public immutable collateral;
    address public immutable oracle;
    bytes32 public immutable matchRef;
    string public question;
    uint256 public endTime;
    uint8 public outcomeCount;
    uint16 public feeBps;

    Status public marketStatus;
    uint8 public winningOutcome;

    uint256[] public pool;
    mapping(address => mapping(uint8 => uint256)) public stake;
    mapping(address => bool) public claimed;

    event Bought(address indexed user, uint8 outcome, uint256 amount);
    event Resolved(uint8 winningOutcome);
    event Claimed(address indexed user, uint256 amount);
    event MarketVoided();

    modifier onlyOracle() {
        require(msg.sender == oracle, "not oracle");
        _;
    }

    constructor(
        address _collateral,
        address _oracle,
        bytes32 _matchRef,
        string memory _question,
        uint256 _endTime,
        uint8 _outcomeCount,
        uint16 _feeBps
    ) {
        require(_outcomeCount >= 2 && _outcomeCount <= 8, "outcomes");
        collateral = IERC20(_collateral);
        oracle = _oracle;
        matchRef = _matchRef;
        question = _question;
        endTime = _endTime;
        outcomeCount = _outcomeCount;
        feeBps = _feeBps;
        for (uint8 i = 0; i < _outcomeCount; i++) {
            pool.push(0);
        }
    }

    function status() external view returns (uint8) {
        return uint8(marketStatus);
    }

    function buy(uint8 outcome, uint256 amount) external nonReentrant {
        require(marketStatus == Status.Open && block.timestamp < endTime, "closed");
        require(outcome < outcomeCount && amount > 0, "invalid");
        uint256 fee = (amount * feeBps) / 10_000;
        uint256 net = amount - fee;
        collateral.safeTransferFrom(msg.sender, address(this), amount);
        pool[outcome] += net;
        stake[msg.sender][outcome] += net;
        emit Bought(msg.sender, outcome, amount);
    }

    function resolve(uint8 _outcome) external onlyOracle {
        require(marketStatus == Status.Open && _outcome < outcomeCount, "invalid");
        marketStatus = Status.Resolved;
        winningOutcome = _outcome;
        emit Resolved(_outcome);
    }

    function voidMarket() external onlyOracle {
        require(marketStatus == Status.Open, "not open");
        marketStatus = Status.Voided;
        emit MarketVoided();
    }

    function claim() external nonReentrant {
        require(!claimed[msg.sender], "claimed");
        uint256 payout;
        if (marketStatus == Status.Resolved) {
            uint256 winPool = pool[winningOutcome];
            require(winPool > 0, "empty");
            uint256 total;
            for (uint8 i = 0; i < outcomeCount; i++) {
                total += pool[i];
            }
            payout = (stake[msg.sender][winningOutcome] * total) / winPool;
        } else if (marketStatus == Status.Voided) {
            for (uint8 i = 0; i < outcomeCount; i++) {
                payout += stake[msg.sender][i];
            }
        } else {
            revert("not claimable");
        }
        require(payout > 0, "nothing");
        claimed[msg.sender] = true;
        collateral.safeTransfer(msg.sender, payout);
        emit Claimed(msg.sender, payout);
    }
}

